UPDATE public.places SET short_description='UNESCO Dünya Mirası Listesi’ndeki Orta Çağ kenti; surları, kilise ve cami kalıntılarıyla öne çıkar.', long_description='Kars’a yaklaşık 42 km uzaklıktaki Ani Örenyeri, Arpaçay kıyısında farklı dönemlerden kalan surlar, dinî yapılar, hamamlar ve diğer kent kalıntılarını barındırır. Sınır bölgesindeki ziyaret kuralları ve açık olma durumu önceden kontrol edilmelidir.', source_url='https://kars.ktb.gov.tr/TR-54868/dunya-miras-listesinde-ani-orenyeri.html', verified=true, trust_score=95, content_review_status='source_backed', updated_at=now() WHERE city='Kars' AND slug='ani-orenyeri';
UPDATE public.places SET short_description='Kars kent merkezine hâkim kayalık yükselti üzerinde yer alan tarihî savunma yapısı.', long_description='Kars Kalesi, kentin tarihî merkezinin üzerinde konumlanır ve Kars’ın savunma geçmişini yansıtan başlıca anıtlardandır.', source_url='https://kars.ktb.gov.tr/TR-54872/kars-kalesi-ve-diger-kaleler.html', verified=true, trust_score=95, content_review_status='source_backed', updated_at=now() WHERE city='Kars' AND slug='kars-kalesi';
UPDATE public.places SET is_active=false, content_review_status='rejected', updated_at=now() WHERE city='Kars' AND slug='osm-way-189989602' AND EXISTS(SELECT 1 FROM public.places p WHERE p.city='Kars' AND p.slug='kars-kalesi' AND p.is_active=true);
UPDATE public.places SET short_description='Kastamonu ve Çankırı sınırlarında uzanan, ormanları ve dağ peyzajıyla öne çıkan millî park.', long_description='Ilgaz Dağı Millî Parkı, Batı Karadeniz’in ormanlık dağ alanlarını ve zengin peyzajını koruyan doğal alandır. Mevsimsel hava ve yol koşulları ziyaret planında dikkate alınmalıdır.', source_url='https://kastamonu.ktb.gov.tr/TR-339263/milli-parklar-ve-korunan-alanlar.html', verified=true, trust_score=95, content_review_status='source_backed', updated_at=now() WHERE city='Kastamonu' AND slug='ilgaz-dagi-milli-parki';
