UPDATE public.places SET short_description='Erciyes Dağı’nın yüksek rakımlı yamaçlarında kış sporları ve dağ turizmi için kullanılan merkez.', long_description='Erciyes Kayak Merkezi, Kayseri’nin simge dağı Erciyes’te kış sporları ve dağ turizmi için kullanılan başlıca alandır. Tesislerin ve pistlerin güncel durumu ziyaret öncesinde kontrol edilmelidir.', source_url='https://kayseri.ktb.gov.tr/TR-55115/gezilecek-yerler.html', verified=true, trust_score=95, content_review_status='source_backed', updated_at=now() WHERE city='Kayseri' AND slug='erciyes-kayak-merkezi';
