UPDATE public.places SET short_description='Istranca ormanları içinde yer alan; kuru ve sulu galerileri, yer altı nehri ve damlataş oluşumlarıyla tanınan mağara sistemi.', long_description='Dupnisa Mağarası, Demirköy yakınlarında bulunan ve Kuru, Kız ve Sulu mağara bölümlerinden oluşan önemli bir yer altı ekosistemidir. Kız Mağarası yarasa yaşamı nedeniyle ziyarete kapalıdır; Sulu Mağara da mevsimsel olarak kapanabilir. Gitmeden önce resmî ziyaret koşullarını kontrol edin.', source_url='https://kirklareli.ktb.gov.tr/TR-64306/magara-turizmi.html', verified=true, trust_score=95, content_review_status='source_backed', updated_at=now() WHERE city='Kırklareli' AND slug='dupnisa-magarasi';
UPDATE public.places SET short_description='Deniz, göl, sazlık ve subasar ormanların bir arada bulunduğu korunan kıyı ekosistemi.', long_description='İğneada Longoz Ormanları Millî Parkı, kıyı gölleri, sulak alanları ve subasar ormanlarıyla öne çıkar. Hassas habitatı korumak için belirlenmiş güzergâhlara ve yerel uyarılara uyulmalıdır.', source_url='https://kirklareli.ktb.gov.tr/TR-64304/doga-ve-doga-yuruyusu-trekking-turizmi.html', verified=true, trust_score=95, content_review_status='source_backed', updated_at=now() WHERE city='Kırklareli' AND slug='igneada-longoz-ormanlari-milli-parki';
